import hashlib,os,pathlib,re,tempfile
def install_compatible(releases,cpu_features,output):
    if not isinstance(cpu_features,list) or any(not isinstance(x,str) for x in cpu_features) or len(cpu_features)!=len(set(cpu_features)) or set(cpu_features)-{'sse2','avx'}:raise ValueError('explicit supported CPU feature list required')
    if not isinstance(releases,list) or not releases:raise ValueError('approved releases required')
    output=pathlib.Path(output);ids=set();priorities=set();validated=[]
    if output.is_symlink():raise ValueError('output symlink forbidden')
    for release in releases:
        if not isinstance(release,dict) or not {'id','priority','requires','path','sha256'}<=set(release) or not isinstance(release['path'],str) or not release['path']:raise ValueError('complete release metadata required')
        ident=release['id'];priority=release['priority'];required=release['requires'];path=pathlib.Path(release['path'])
        if not isinstance(ident,str) or not ident or ident in ids or type(priority) is not int or priority in priorities:raise ValueError('unique release IDs and integer priorities required')
        if not isinstance(required,list) or any(not isinstance(x,str) for x in required) or len(required)!=len(set(required)) or set(required)-{'sse2','avx'}:raise ValueError('unknown required CPU feature')
        if path.is_symlink() or not path.is_file() or output.resolve()==path.resolve():raise ValueError('regular artifact and separate output required')
        data=path.read_bytes();sha=release['sha256']
        if not isinstance(sha,str) or not re.fullmatch('[a-f0-9]{64}',sha) or hashlib.sha256(data).hexdigest()!=sha:raise ValueError('artifact SHA256 mismatch')
        ids.add(ident);priorities.add(priority);validated.append((release,data))
    compatible=[pair for pair in validated if set(pair[0]['requires'])<=set(cpu_features)]
    if not compatible:raise ValueError('no approved CPU-compatible release')
    selected,data=max(compatible,key=lambda pair:pair[0]['priority'])
    fd,name=tempfile.mkstemp(prefix='.release-',dir=output.parent)
    try:
        with os.fdopen(fd,'wb') as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
        os.chmod(name,0o755);os.replace(name,output)
    finally:
        if os.path.exists(name):os.unlink(name)
    return {'id':selected['id'],'sha256':selected['sha256']}
```

